    (function () {
      var root = document.getElementById('products');
      if (!root) return;
      var tabs = root.querySelectorAll('.j2-tab');
      var cards = root.querySelectorAll('.j2-product');
      var count = document.getElementById('products-count');

      function apply(category) {
        var shown = 0;
        for (var i = 0; i < cards.length; i++) {
          var match = category === 'all' || cards[i].getAttribute('data-category') === category;
          cards[i].hidden = !match;
          if (match) shown++;
        }
        for (var j = 0; j < tabs.length; j++) {
          var active = tabs[j].getAttribute('data-category') === category;
          tabs[j].classList.toggle('is-active', active);
          tabs[j].setAttribute('aria-pressed', active ? 'true' : 'false');
        }
        if (count) count.textContent = 'Showing ' + shown + ' of ' + cards.length + ' products';
      }

      for (var k = 0; k < tabs.length; k++) {
        tabs[k].addEventListener('click', function () {
          apply(this.getAttribute('data-category'));
        });
      }
      apply('all');
    })();
