  (function () {
    var NUMBER = '910000011111';
    var ICON = '<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false"><path d="M12 2a10 10 0 0 0-8.6 15.1L2 22l5-1.3A10 10 0 1 0 12 2zm0 18.2a8.2 8.2 0 0 1-4.2-1.2l-.3-.2-3 .8.8-2.9-.2-.3A8.2 8.2 0 1 1 12 20.2zm4.5-6.1c-.2-.1-1.5-.7-1.7-.8-.2-.1-.4-.1-.6.1l-.8 1c-.1.2-.3.2-.5.1a6.700 6.700 0 0 1-3.300-2.900c-.2-.4.2-.4.700-1.300.1-.2 0-.3 0-.5l-.8-1.900c-.2-.5-.4-.4-.6-.4h-.5c-.2 0-.5.1-.7.300-.2.300-.9.900-.9 2.200s.9 2.500 1.100 2.700c.1.200 1.800 2.800 4.400 3.900 1.600.7 2.300.7 3.100.6.500-.1 1.500-.6 1.700-1.200.2-.6.2-1.100.2-1.200-.1-.1-.3-.2-.5-.3z"/></svg>';

    function addButtons() {
      var cards = document.querySelectorAll('#products .j2-product');
      for (var i = 0; i < cards.length; i++) {
        var card = cards[i];
        var slot = card.querySelector('.j2-card-actions');
        if (!slot || slot.querySelector('.j2-order-btn')) continue;
        var name = card.getAttribute('data-name');
        if (!name) {
          var h = card.querySelector('.j2-name');
          name = h ? h.textContent.trim() : '';
        }
        if (!name) continue;
        var message = 'Hi Thread & Loom, I would like to order: ' + name;
        var a = document.createElement('a');
        a.className = 'j2-btn j2-order-btn';
        a.href = 'https://wa.me/' + NUMBER + '?text=' + encodeURIComponent(message);
        a.target = '_blank';
        a.rel = 'noopener noreferrer';
        a.setAttribute('aria-label', 'Order ' + name + ' on WhatsApp');
        a.innerHTML = ICON + '<span>Order on WhatsApp</span>';
        slot.appendChild(a);
      }
    }

    if (document.readyState === 'loading') {
      document.addEventListener('DOMContentLoaded', addButtons);
    } else {
      addButtons();
    }
  })();
</script>
