      var sizeSel = document.getElementById('filter-size');
      var priceSel = document.getElementById('filter-price');
      var resetBtn = document.getElementById('filters-reset');
      var form = document.getElementById('filters-form');
      var empty = document.getElementById('filters-empty');
      var cards = products.querySelectorAll('.j2-product');
      var tabs = products.querySelectorAll('.j2-tab');

      panel.className = (panel.className + ' j2-card').replace(/^\s+/, '');
      if (count && count.parentNode === products) {
        products.insertBefore(panel, count);
      }

      function sizeOk(card, size) {
        if (size === 'all') return true;
        var list = (card.getAttribute('data-sizes') || '').split(',');
        for (var i = 0; i < list.length; i++) {
          var s = list[i].replace(/\s+/g, '').toUpperCase();
          if (s === 'FREE' || s === size) return true;
        }
        return false;
      }

      function priceOk(card, range) {
        if (range === 'all') return true;
        var parts = range.split('-');
        var lo = parseInt(parts[0], 10);
        var hi = parseInt(parts[1], 10);
        var price = parseInt(card.getAttribute('data-price'), 10);
        if (isNaN(price)) return true;
        return price >= lo && price <= hi;
      }

      function apply() {
        var size = sizeSel.value;
        var range = priceSel.value;
        var visible = 0;
        for (var i = 0; i < cards.length; i++) {
          var pass = sizeOk(cards[i], size) && priceOk(cards[i], range);
          cards[i].classList.toggle('j2-filtered-out', !pass);
          if (pass && !cards[i].hidden) visible++;
        }
        if (count) count.textContent = 'Showing ' + visible + ' of ' + cards.length + ' products';
        if (empty) empty.hidden = visible !== 0;
      }

      sizeSel.addEventListener('change', apply);
      priceSel.addEventListener('change', apply);
      form.addEventListener('submit', function (e) { e.preventDefault(); });
      resetBtn.addEventListener('click', function () {
        sizeSel.value = 'all';
        priceSel.value = 'all';
        apply();
      });

      /* Category tabs (W-1) set card.hidden first; recount afterwards so the filters stack on top. */
      for (var t = 0; t < tabs.length; t++) {
        tabs[t].addEventListener('click', apply);
      }

      apply();
    })();
